Future<List<Item>> enrich(List<String> ids, Repository repository) async {
  final results = ResultListFactory.create();
  for (final item in await repository.loadMany(ids)) {
    if (item.active) {
      if (item.owner != null) {
        if (item.owner!.enabled) results.add(item);
      }
    }
  }
  return results;
}

